{"cmd":"LC_ALL=C LINES=100000 top -b -d 1 -n 11 -w 512 | awk '
BEGIN { batch=0; samples=0 }
/^top -/ { batch++; next }
/^%Cpu\(s\):/ && batch > 1 {
  idle=$8; usage=100-idle;
  samples++;
  total+=usage;
  if (samples==1 || usage<min) min=usage;
  if (samples==1 || usage>max) max=usage;
  cpu[samples]=usage;
  next
}
batch > 1 && $1 ~ /^[0-9]+$/ && $9 ~ /^[0-9.]+$/ {
  key=$1 SUBSEP $12;
  sum[key]+=$9;
  seen[key]++;
  if ($9>pmax[key]) pmax[key]=$9;
  user[key]=$2;
}
END {
  printf "CPU_SAMPLES";
  for (i=1;i<=samples;i++) printf " %.1f", cpu[i];
  printf "\nCPU_AVG %.2f\nCPU_MIN %.2f\nCPU_MAX %.2f\n", total/samples, min, max;
  best=""; bestavg=-1;
  for (k in sum) {
    avg=sum[k]/samples;
    if (avg>bestavg) { bestavg=avg; best=k }
  }
  split(best,a,SUBSEP);
  printf "TOP_PID %s\nTOP_USER %s\nTOP_COMMAND %s\nTOP_AVG_CPU %.2f\nTOP_MAX_CPU %.2f\nTOP_SEEN %d/%d\n", a[1], user[best], a[2], bestavg, pmax[best], seen[best], samples;
}'","workdir":"/home/unitree","yield_time_ms":30000,"max_output_tokens":12000}

